addwall:
static void lns_original_addwall(float x, float z, float x1, float x2, float x3, float x4, float depth, float alt, int type, int ignore_projectile_wall_collision)
{
    __realloc(level->walls, level->numwalls);
    level->walls[level->numwalls].x = x;
    level->walls[level->numwalls].z = z;
    level->walls[level->numwalls].upperleft = x1;
    level->walls[level->numwalls].lowerleft = x2;
    level->walls[level->numwalls].upperright = x3;
    level->walls[level->numwalls].lowerright = x4;
    level->walls[level->numwalls].depth = depth;
    level->walls[level->numwalls].height = alt;
    level->walls[level->numwalls].type = type;
    level->walls[level->numwalls].ignore_projectile_wall_collision = ignore_projectile_wall_collision;

    level->numwalls++;
}

adjust_prefix:
void adjust_base(entity *e, entity **pla)
{
    int wall = -1, hole = -1;
    float seta = 0, maxbase = 0;
    entity *other = NULL, *plat, *tempself;

    tempself = self;
    self = e;

    if(self->velocity.y > 0)
    {
        self->landed_on_platform = NULL;
    }

    if(self->modeldata.subject_to_platform > 0)
    {
        other = check_platform_below_entity(self);
        if(!other && self->landed_on_platform)
        {
            *pla = self->landed_on_platform = NULL;
        }
    }
    else
    {
        *pla = other = self->landed_on_platform = NULL;
    }

    // Avoid base adjustement in projectiles when the platform detected is marked to be ignored
    if((self->spawntype == SPAWN_TYPE_PROJECTILE_NORMAL || self->spawntype == SPAWN_TYPE_PROJECTILE_BOMB) &&
    other && (other->modeldata.ignore_projectile_wall_collision || other->modeldata.type == TYPE_OBSTACLE))
    {
        return;
    }

